from typing import List

def calculate_minimum_cost(n: int, s: str, c: List[int]) -> int:
    min_cost = float('inf')

    for i in range(n - 1):
        if s[i] != s[i + 1]:
            # Calculate the cost to make s[i] and s[i+1] the same
            cost = min(c[i], c[i + 1])
            min_cost = min(min_cost, cost)

    return min_cost
